{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Cohort-based wellness coaching that builds habits, outcomes, and repeatable frameworks across your days.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-split">
  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <ul>
          <li><a href="/programs.html">Programs</a></li>
          <li><a href="/about.html">Meet</a></li>
          <li><a href="/services.html">Offerings</a></li>
          <li><a href="/testimonials.html">Stories</a></li>
          <li><a href="/book.html">Book</a></li>
          <li><a href="/contact.html">Contact</a></li>
        </ul>
      </nav>
      <div class="actions">
        <a class="btn btn-secondary" href="/pricing.html">Pricing</a>
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
      <button class="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <section class="hero split-diagonal" aria-labelledby="hero-head">
      <div class="hero-left">
        <h1 id="hero-head">Right-sized routines for clearer days</h1>
        <p class="lead">Join a small cohort of peers to learn frameworks that nudge outcomes forward without adding noise. Built around habits, not hype.</p>
        <p class="meta">Cohorts run seasonally — practical check-ins, short modules, measurable rituals.</p>
        <div class="hero-ctas">
          <a class="btn btn-ghost" href="/programs.html">See cohorts</a>
          <button id="tryItBtn" class="btn btn-accent">Try it now — quick exercise</button>
        </div>
        <ul class="contact-inline">
          <li>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></li>
          <li>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
        </ul>
      </div>
      <div class="hero-right" aria-hidden="true">
        <div class="pattern-wrap">
          <svg class="decor" viewBox="0 0 400 300" preserveAspectRatio="none" aria-hidden="true">
            <defs>
              <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse" patternTransform="rotate(20)">
                <rect width="40" height="40" fill="rgba(255,255,255,0.02)"></rect>
                <circle cx="8" cy="8" r="2" fill="rgba(255,255,255,0.06)"></circle>
                <circle cx="32" cy="32" r="2.5" fill="rgba(255,255,255,0.04)"></circle>
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p)"></rect>
          </svg>
          <div class="mock-card" aria-hidden="true">
            <h3>Micro-habit map</h3>
            <p>Three simple daily anchors — movement, pause, tidy — mapped to your week.</p>
            <ul>
              <li>10m Morning Focus</li>
              <li>5m Midday Pause</li>
              <li>Evening review</li>
            </ul>
          </div>
        </div>
      </div>
    </section>

    <section class="what-to-expect" data-reveal>
      <div class="wrap">
        <h2>What to expect in a cohort</h2>
        <div class="cards">
          <article>
            <h3>Outcomes-first weeks</h3>
            <p>Each module starts with one measurable outcome, then we work backward to the smallest daily moves that produce it.</p>
          </article>
          <article>
            <h3>Habit frameworks</h3>
            <p>Simple scaffolds you can apply across contexts: cue, micro-action, prompt, reward — tested in-group before you scale them.</p>
          </article>
          <article>
            <h3>Accountability that doesn't nag</h3>
            <p>Weekly group check-ins and compact templates keep progress visible without taking over your calendar.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="gallery" data-reveal>
      <div class="wrap">
        <h2>Snapshots from recent cohorts</h2>
        <div class="grid">
          <div class="tile">Morning rituals</div>
          <div class="tile">Micro-goals</div>
          <div class="tile">Weekly syncs</div>
          <div class="tile">Reflection prompts</div>
        </div>
      </div>
    </section>

    <section class="objections" data-reveal>
      <div class="wrap">
        <h2>Is this for you?</h2>
        <ul class="faq">
          <li><strong>I don't have time.</strong> The cohorts center around tiny, repeatable habits. Expect 10–20 min/day of deliberate practice.</li>
          <li><strong>Is it coaching or therapy?</strong> Coaching focused on outcomes, habits, and frameworks — not medical or therapeutic claims.</li>
          <li><strong>Can I join mid-cycle?</strong> Some cohorts accept rolling joiners; check the programs page to see options.</li>
        </ul>
      </div>
    </section>

    <section class="cta" data-reveal>
      <div class="wrap">
        <h2>Ready to shape your weeks?</h2>
        <p>Join a small seasonal cohort and walk away with a repeatable plan you actually use.</p>
        <div class="cta-actions">
          <a class="btn btn-primary" href="/programs.html">View upcoming cohorts</a>
          <a class="btn btn-outline" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
        <p class="local">Serving {{CITY}}, {{STATE}} and remote cohorts worldwide.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Small cohorts, steady results.</p>
      <nav class="foot-nav">
        <a href="/about.html">About</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/contact.html">Contact</a>
      </nav>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="exerciseModal" class="modal" aria-hidden="true" role="dialog" aria-labelledby="exerciseTitle">
    <div class="modal-panel">
      <button class="modal-close" id="modalClose" aria-label="Close">✕</button>
      <h2 id="exerciseTitle">Try a mini practice</h2>
      <p class="muted">Select an option, then follow the prompts. Exercises are 2–6 minutes.</p>
      <div class="exercise-options">
        <button class="ex-btn" data-type="breathing">Breathing — 2 min</button>
        <button class="ex-btn" data-type="journaling">Journaling — 5 min</button>
        <button class="ex-btn" data-type="intention">Intention setting — 3 min</button>
      </div>

      <div id="exerciseArea" class="exercise-area" aria-live="polite"></div>

    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
