{"path":"assets/css/styles.css","content":"/* Core variables */
:root{
  --bg:#0f1720;
  --card:#0b1220;
  --muted:#9aa4b2;
  --accent:#ff7a59;
  --accent-2:#ffd8b5;
  --glass:rgba(255,255,255,0.04);
  --radius:12px;
  --max:1100px;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, monospace;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, Roboto, "Helvetica Neue", Arial; background:linear-gradient(180deg,#07101a 0%, #0b1220 100%); color:#e6eef6; -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:24px}
.site-header{position:sticky;top:0;background:linear-gradient(180deg,rgba(2,6,11,0.6),transparent);backdrop-filter:blur(6px);z-index:40}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.logo{font-weight:700;color:var(--accent);text-decoration:none}
.nav ul{list-style:none;margin:0;padding:0;display:flex;gap:12px}
.nav a{color:inherit;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a:hover{background:var(--glass)}
.actions{margin-left:auto;display:flex;gap:8px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}
.btn-primary{background:linear-gradient(90deg,var(--accent),#ffb28b);color:#08101a}
.btn-secondary{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--accent-2)}
.btn-ghost{background:transparent;border:1px dashed rgba(255,255,255,0.03);color:var(--muted)}
.btn-accent{background:transparent;border:2px solid var(--accent);color:var(--accent)}
.btn-outline{background:transparent;border:1px solid rgba(255,255,255,0.06)}
.nav-toggle{display:none;background:none;border:0;color:inherit;font-size:20px}

/* Hero split diagonal */
.hero{display:flex;min-height:64vh;align-items:center;overflow:hidden}
.hero-left{flex:1;padding:48px}
.hero-right{flex:1;position:relative;display:flex;align-items:center;justify-content:center;padding:48px}
.split-diagonal{background-image:url('/assets/img/pattern.svg');background-repeat:repeat;background-size:300px}
.hero::before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent,rgba(2,6,11,0.25));pointer-events:none}
.hero-right .pattern-wrap{width:100%;max-width:420px;height:320px;border-radius:var(--radius);background:linear-gradient(135deg,rgba(255,255,255,0.02),rgba(255,255,255,0.00));box-shadow:0 8px 30px rgba(2,6,11,0.6);padding:20px;display:flex;flex-direction:column;gap:12px}
.mock-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:10px}
.lead{color:var(--accent-2);font-size:18px}
.meta{color:var(--muted);font-size:14px}
.contact-inline{list-style:none;padding:0;margin-top:12px;display:flex;gap:12px;color:var(--muted)}

/* Sections */
section{padding:48px 0}
.what-to-expect .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
.cards article{background:var(--card);padding:18px;border-radius:10px}
.gallery .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.tile{background:linear-gradient(90deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:28px;border-radius:10px;text-align:center;color:var(--muted)}
.objections .faq{list-style:none;padding:0}
.objections li{background:var(--card);padding:14px;border-radius:10px;margin-bottom:10px}
.cta{background:linear-gradient(180deg,rgba(255,120,89,0.06),transparent);border-radius:14px}
.cta-actions{display:flex;gap:12px;margin-top:12px}
.local{color:var(--muted);font-size:13px;margin-top:10px}

/* Footer */
.site-footer{padding:20px 0;color:var(--muted)}
.site-footer .wrap{display:flex;align-items:center;justify-content:space-between}
.foot-nav a{color:var(--muted);text-decoration:none;margin-left:12px}

/* Modal and exercise */
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(2,6,11,0.6);z-index:60}
.modal[aria-hidden="false"]{display:flex}
.modal-panel{background:linear-gradient(180deg,#07101a,#0b1220);padding:20px;border-radius:14px;min-width:320px;max-width:720px;color:#eaf4ff;position:relative}
.modal-close{position:absolute;right:12px;top:12px;background:none;border:0;color:var(--muted);font-size:18px}
.exercise-options{display:flex;gap:8px;margin:8px 0}
.ex-btn{flex:1;padding:10px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03);color:var(--accent-2)}
.exercise-area{margin-top:12px}
.breath-circle{width:160px;height:160px;border-radius:50%;margin:18px auto;background:radial-gradient(circle at 30% 30%, rgba(255,255,255,0.06), rgba(255,255,255,0.02));display:flex;align-items:center;justify-content:center;color:var(--accent);font-weight:700}
.breathing{transition:transform 1400ms ease-in-out}
.timer{color:var(--muted);font-family:var(--mono);margin-top:8px;text-align:center}

/* Reveal states */
[data-reveal]{opacity:0;transform:translateY(16px);transition:opacity 600ms ease, transform 600ms ease}
[data-reveal].visible{opacity:1;transform:none}
@media (prefers-reduced-motion: reduce){
  [data-reveal]{transition:none;transform:none}
}

/* Responsive */
@media (max-width:900px){
  .hero{flex-direction:column}
  .hero-right{order:-1;width:100%}
  .what-to-expect .cards{grid-template-columns:1fr}
  .gallery .grid{grid-template-columns:repeat(2,1fr)}
  .nav{display:none}
  .nav-toggle{display:block}
}

/* Small helpers */
.muted{color:var(--muted)}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function qs(sel, root) { return (root||document).querySelector(sel); }
  function qsa(sel, root) { return Array.from((root||document).querySelectorAll(sel)); }

  // Year in footer
  qs('#year').textContent = new Date().getFullYear();

  // Mobile nav toggle
  const navToggle = qs('.nav-toggle');
  navToggle && navToggle.addEventListener('click', function(){
    document.body.classList.toggle('nav-open');
    const nav = qs('.nav');
    if(nav) nav.style.display = nav.style.display === 'flex' ? 'none' : 'flex';
  });

  // Scroll-triggered reveals with prefers-reduced-motion support
  const prefsReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const reveals = qsa('[data-reveal]');

  if(prefsReduced){
    reveals.forEach(el => el.classList.add('visible'));
  } else if('IntersectionObserver' in window){
    const obs = new IntersectionObserver((entries)=>{
      entries.forEach(e => {
        if(e.isIntersecting){
          e.target.classList.add('visible');
          obs.unobserve(e.target);
        }
      });
    },{threshold:0.12});
    reveals.forEach(el => obs.observe(el));
  } else {
    // fallback
    const onScroll = function(){
      const top = window.scrollY + window.innerHeight*0.9;
      reveals.forEach(el=>{
        if(el.getBoundingClientRect().top + window.scrollY < top){ el.classList.add('visible'); }
      });
    };
    onScroll();window.addEventListener('scroll', onScroll);
  }

  // Modal and Guided Exercise
  const modal = qs('#exerciseModal');
  const tryItBtn = qs('#tryItBtn');
  const closeBtn = qs('#modalClose');
  const exArea = qs('#exerciseArea');
  let currentTimer = null;

  function openModal(){
    modal.setAttribute('aria-hidden','false');
    document.body.style.overflow = 'hidden';
    qs('.modal-panel').focus && qs('.modal-panel').focus();
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
    clearExercise();
  }
  function clearExercise(){
    exArea.innerHTML='';
    if(currentTimer) { clearInterval(currentTimer); currentTimer=null; }
  }

  tryItBtn && tryItBtn.addEventListener('click', ()=>{ openModal(); });
  closeBtn && closeBtn.addEventListener('click', ()=>{ closeModal(); });
  modal.addEventListener('click', (e)=>{ if(e.target === modal) closeModal(); });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeModal(); });

  // Exercise handlers
  qsa('.ex-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const type = btn.getAttribute('data-type');
      startExercise(type);
    });
  });

  function startExercise(type){
    clearExercise();
    if(type==='breathing') startBreathing();
    if(type==='journaling') startJournaling();
    if(type==='intention') startIntention();
  }

  // Breathing exercise (visual circle + guided counts)
  function startBreathing(){
    const duration = 120; // seconds
    const circle = document.createElement('div');
    circle.className = 'breath-circle';
    circle.innerHTML = '<div class="breathing" id="breathAnim">Breathe</div>';
    const timer = document.createElement('div'); timer.className='timer'; timer.textContent = formatTime(duration);
    exArea.appendChild(circle); exArea.appendChild(timer);

    let remaining = duration;
    const phases = [4,6,6]; // inhale, hold, exhale (seconds)
    let phaseIndex = 0; let phaseRemain = phases[0];
    const animEl = qs('#breathAnim');

    function stepPhase(){
      // simple visual: scale on inhale, hold, shrink on exhale
      if(phaseIndex===0){ animEl.style.transform='scale(1.18)'; animEl.textContent='Inhale'; }
      else if(phaseIndex===1){ animEl.style.transform='scale(1.18)'; animEl.textContent='Hold'; }
      else { animEl.style.transform='scale(0.86)'; animEl.textContent='Exhale'; }
    }
    stepPhase();

    currentTimer = setInterval(()=>{
      remaining--; phaseRemain--;
      timer.textContent = formatTime(remaining);
      if(phaseRemain<=0){
        phaseIndex = (phaseIndex+1)%phases.length; phaseRemain = phases[phaseIndex]; stepPhase();
      }
      if(remaining<=0){ clearInterval(currentTimer); currentTimer=null; timer.textContent='Done — nice work!'; animEl.textContent='Done'; animEl.style.transform='scale(1)'; }
    },1000);
  }

  function formatTime(sec){ const m = Math.floor(sec/60); const s = sec%60; return `${m}:${s.toString().padStart(2,'0')}`; }

  // Journaling exercise: prompt + timer + save to localStorage
  function startJournaling(){
    const seconds = 300; // 5 minutes
    const prompt = choosePrompt();
    const p = document.createElement('p'); p.className='muted'; p.textContent = 'Prompt: ' + prompt;
    const ta = document.createElement('textarea'); ta.style.width='100%'; ta.style.minHeight='120px'; ta.placeholder='Write freely for 5 minutes...';
    const timer = document.createElement('div'); timer.className='timer'; timer.textContent = formatTime(seconds);
    const saveBtn = document.createElement('button'); saveBtn.className='btn btn-ghost'; saveBtn.textContent='Save entry';
    saveBtn.addEventListener('click', ()=>{ saveEntry(ta.value, prompt); saveBtn.textContent='Saved'; setTimeout(()=>saveBtn.textContent='Save entry',2000); });
    exArea.appendChild(p); exArea.appendChild(ta); exArea.appendChild(timer); exArea.appendChild(saveBtn);

    let rem = seconds;
    currentTimer = setInterval(()=>{
      rem--; timer.textContent = formatTime(rem);
      if(rem<=0){ clearInterval(currentTimer); currentTimer=null; timer.textContent='Time up — well done!'; }
    },1000);
  }

  function choosePrompt(){
    const prompts = [
      'What small action would make today slightly better?',
      'Name one worry and one next step you can take about it.',
      'What did you notice about your energy today?'
    ];
    return prompts[Math.floor(Math.random()*prompts.length)];
  }
  function saveEntry(text, prompt){
    const entries = JSON.parse(localStorage.getItem('journalEntries')||'[]');
    entries.push({t:Date.now(), prompt:prompt, text:text});
    localStorage.setItem('journalEntries', JSON.stringify(entries));
  }

  // Intention setter: quick form + save
  function startIntention(){
    const p = document.createElement('p'); p.className='muted'; p.textContent = 'Set a short intention for the rest of your day.';
    const input = document.createElement('input'); input.type='text'; input.placeholder='I intend to...'; input.style.width='100%'; input.style.padding='8px'; input.style.borderRadius='8px'; input.style.border='1px solid rgba(255,255,255,0.04)';
    const saveBtn = document.createElement('button'); saveBtn.className='btn btn-primary'; saveBtn.textContent='Set intention';
    const saved = document.createElement('div'); saved.className='muted'; saved.style.marginTop='8px';
    saveBtn.addEventListener('click', ()=>{
      const val = input.value.trim(); if(!val) return; const key = 'intentions'; const list = JSON.parse(localStorage.getItem(key)||'[]'); list.push({t:Date.now(), text:val}); localStorage.setItem(key, JSON.stringify(list)); saved.textContent='Saved: "'+val+'"'; input.value='';
    });
    exArea.appendChild(p); exArea.appendChild(input); exArea.appendChild(saveBtn); exArea.appendChild(saved);
  }

})();
"} 
